import pandas as pd
import numpy as np
from scipy.stats import zscore

# Load the datasets
df = pd.read_csv(DATASET_PATH)
adjacency_df = pd.read_csv(ADJACENCY_PATH)

# Merge the datasets
merged_df = pd.merge(df, adjacency_df, how='inner', on='borough')

# Calculate the z-score for the energy values
merged_df['zscore'] = zscore(merged_df['Energy_value'])

# Create a dictionary to store the boroughs and their neighbors' z-scores
borough_dict = {}

for index, row in merged_df.iterrows():
    if row['borough'] not in borough_dict:
        borough_dict[row['borough']] = {'zscore': row['zscore'], 'neighbors_zscore': []}
    borough_dict[row['borough']]['neighbors_zscore'].append(merged_df[merged_df['borough'] == row['neighbor']]['zscore'].values[0])

# Calculate the local Moran's I for each borough
for borough in borough_dict:
    borough_dict[borough]['local_moran'] = borough_dict[borough]['zscore'] * np.mean(borough_dict[borough]['neighbors_zscore'])

# Identify the hot and cold spots
hot_spots = []
cold_spots = []

for borough in borough_dict:
    if borough_dict[borough]['local_moran'] > 0:
        if borough_dict[borough]['zscore'] > 0:
            hot_spots.append((borough, borough_dict[borough]['local_moran']))
        else:
            cold_spots.append((borough, borough_dict[borough]['local_moran']))

# Print the hot and cold spots
final_answer = []

for borough, local_moran in hot_spots:
    final_answer.append(f"{borough} (HH, local_moran={local_moran})")

for borough, local_moran in cold_spots:
    final_answer.append(f"{borough} (LL, local_moran={local_moran})")

if not final_answer:
    final_answer.append("none")

print("FINAL ANSWER: " + ", ".join(final_answer))
